import AppKit

/// Eingebettetes REWE-Logo (PNG, base64) — selbst-enthalten, ohne Resource-Bundle
/// (vermeidet die Bundle.module-Falle). Genutzt für Menüleiste + Flyout des
/// REWE-eBon-Slots.
enum ReweLogoAsset {
    static let image: NSImage? = {
        guard let data = Data(base64Encoded: base64) else { return nil }
        return NSImage(data: data)
    }()

    private static let base64 = """

"""
}
